const spiderAnchors=[['explore','Explore','A web node is tucked by the discovery scene.'],['activity','Activity','Follow a thread near your activity trail.'],['community','Campus','Find the connection on the campus board.'],['map','Map','Look for a pin-side web glint.'],['profile','Profile','Check the edge of your profile card.'],['list','List item','A small strand waits by the listing form.']];
