function readSpiderAnchors(){try{return {found:[],sense:false,master:false,...JSON.parse(localStorage.getItem(spiderAnchorKey)||'{}')}}catch{return {found:[],sense:false,master:false}}}
let spiderAnchorState=readSpiderAnchors(),spiderWeaveStep=0;
function saveSpiderAnchors(){try{localStorage.setItem(spiderAnchorKey,JSON.stringify(spiderAnchorState))}catch{}}
function paintSpiderMissions(){const panel=document.querySelector('.spider-mission-panel');if(!panel)return;const all=spiderAnchorState.found.length===spiderAnchors.length;panel.innerHTML=`<div class="spider-mission-head"><div><span>THE SIX WEB ANCHORS</span><b>${spiderAnchorState.master?'Neighborhood web complete!':`${spiderAnchorState.found.length} of 6 anchors found`}</b></div><strong>${spiderAnchorState.found.length}/6</strong></div><ol>${spiderAnchors.map(([id,name,hint],index)=>`<li class="${spiderAnchorState.found.includes(id)?'is-done':''}"><span>${spiderAnchorState.found.includes(id)?'✓':String(index+1).padStart(2,'0')}</span><div><b>${name}</b><small>${spiderAnchorState.found.includes(id)?'Anchor connected':hint}</small></div><strong>${spiderAnchorState.found.includes(id)?'LINKED':'HIDDEN'}</strong></li>`).join('')}</ol><p>Explore all six pages and tap each hidden web node. Progress stays on this device and never affects credits.</p>${all&&!spiderAnchorState.master?'<button class="spider-weave-start" type="button">Connect the web</button>':''}${spiderAnchorState.master?'<div class="spider-weave-badge">✦ WEB-WEAVER · THEME BADGE UNLOCKED</div>':''}`;panel.querySelector('.spider-weave-start')?.addEventListener('click',startSpiderWeaveChallenge)}
function completeSpiderAnchor(id){if(document.body.dataset.theme!=='web-slinger'||spiderAnchorState.found.includes(id))return;spiderAnchorState.found.push(id);saveSpiderAnchors();paintSpiderMissions();const toggle=document.querySelector('.spider-missions-toggle');if(toggle){toggle.querySelector('b').textContent=spiderAnchorState.found.length+'/6';toggle.classList.remove('spider-mission-pop');void toggle.offsetWidth;toggle.classList.add('spider-mission-pop')}const mascot=document.querySelector('.spider-mascot');mascot?.classList.add('spider-celebrate');setTimeout(()=>mascot?.classList.remove('spider-celebrate'),750);showSpiderQuote(['Nice discovery!','Web node connected.','The next clue is waiting on another page.'][spiderAnchorState.found.length%3]);if(spiderAnchorState.found.length===spiderAnchors.length)document.querySelector('.spider-hero-badge')?.removeAttribute('hidden')}
function completeSpiderMission(){} // Kept as a no-op for older item/detail hooks; progress now requires deliberate anchor taps.
function showSpiderQuote(line){const quote=document.querySelector('.spider-verse-quote');if(!quote)return;quote.textContent=line;quote.hidden=false;quote.classList.remove('spider-quote-pop');void quote.offsetWidth;quote.classList.add('spider-quote-pop');clearTimeout(window.spiderQuoteTimer);window.spiderQuoteTimer=setTimeout(()=>{quote.hidden=true},3600)}
function startSpiderWeaveChallenge(){spiderWeaveStep=0;const panel=document.querySelector('.spider-mission-panel');if(!panel)return;panel.querySelector('.spider-weave-challenge')?.remove();const game=document.createElement('section');game.className='spider-weave-challenge';game.setAttribute('aria-label','Final web connection challenge');game.innerHTML=`<b>FINAL CONNECTION</b><p>Connect the six anchors in this pattern: Campus → Map → Explore → Activity → List item → Profile.</p><div>${spiderWeaveOrder.map((id,index)=>`<button type="button" data-weave-node="${id}" aria-label="Web node ${index+1}">${index+1}</button>`).join('')}</div><small aria-live="polite">Tap the nodes in order.</small>`;panel.append(game);game.querySelectorAll('[data-weave-node]').forEach(button=>button.addEventListener('click',()=>{const status=game.querySelector('small');if(button.dataset.weaveNode!==spiderWeaveOrder[spiderWeaveStep]){spiderWeaveStep=0;game.querySelectorAll('button').forEach(node=>node.classList.remove('is-connected'));status.textContent='Thread slipped. Start the pattern again.';return}button.classList.add('is-connected');spiderWeaveStep++;status.textContent=spiderWeaveStep===spiderWeaveOrder.length?'The web is connected!':'Node '+spiderWeaveStep+' of 6 connected.';if(spiderWeaveStep===spiderWeaveOrder.length){spiderAnchorState.master=true;saveSpiderAnchors();paintSpiderMissions();document.body.classList.add('spider-web-master');setTimeout(()=>document.body.classList.remove('spider-web-master'),1800);showSpiderQuote('Every connection matters. Web-Weaver unlocked!')}}))}
function mountSpiderPageAnchor(){document.querySelectorAll('.spider-page-anchor').forEach(node=>node.remove());document.querySelectorAll('.spider-anchor-host').forEach(node=>node.classList.remove('spider-anchor-host'));if(document.body.dataset.theme!=='web-slinger')return;const anchorScreen=document.querySelector('#list-dialog')?.open?'list':screen;const [id,name]=spiderAnchors.find(row=>row[0]===anchorScreen)||[];if(!id||spiderAnchorState.found.includes(id))return;const selectors={explore:'.hero',activity:'.activity-list',community:'.community-toolbar',map:'.campus-map,.real-map,.map-layout',profile:'.theme-grid,.profile-card,#screen-content h1',list:'#list-dialog .pickup-section,#list-dialog'};let target=document.querySelector(selectors[id]);if(!target)target=app.querySelector('h1,h2,section');if(!target)return;target.classList.add('spider-anchor-host');const button=document.createElement('button');button.type='button';button.className='spider-page-anchor';button.dataset.spiderAnchor=id;button.setAttribute('aria-label',`Discover hidden ${name} web anchor`);button.title='A hidden web anchor';button.innerHTML='<span aria-hidden="true">✳</span>';target.append(button);button.addEventListener('click',event=>{event.stopPropagation();completeSpiderAnchor(id);button.remove()})}
