function playCommonRouteTransition(page){
 document.querySelector('.borrowed-common-transition')?.remove();
 const names={explore:'EXPLORE',activity:'ACTIVITY',community:'CAMPUS',map:'CAMPUS MAP',profile:'PROFILE',list:'LIST ITEM',notifications:'NOTIFICATIONS'};
 const scene=document.createElement('div');
 scene.className='borrowed-common-transition';
 scene.setAttribute('aria-hidden','true');
 scene.innerHTML=`<span>${names[page]||'NEXT PAGE'}</span>`;
 document.body.append(scene);
 return scene;
}
function go(next){
 if(next===screen||friendsNavigationTimer)return;
 const theme=document.body.dataset.theme;
 const worlds=window.BorrowedThemeWorlds?.supports(theme);
 if(theme==='web-slinger'||worlds){
  clearTimeout(pageTransitionTimer);
  if(theme==='web-slinger')playHeroThemePageTransition(next,theme);else window.BorrowedThemeWorlds.transition(next,theme);
  screen=next;
  app.classList.remove('world-page-enter','spider-page-enter','world-page-exit');
  void app.offsetWidth;
  app.classList.add('world-page-exit');
  window.scrollTo({top:0,behavior:'smooth'});
  pageTransitionTimer=setTimeout(()=>{
   app.classList.remove('world-page-exit');
   render();app.dataset.friendsScene=next;
   if(theme==='web-slinger'){
    completeSpiderMission(next);delete app.dataset.heroTheme;app.dataset.spiderRoute=next;
    app.classList.remove('spider-page-enter');void app.offsetWidth;app.classList.add('spider-page-enter');
   }else window.BorrowedThemeWorlds.arrive(next,theme);
  },430);
  return;
 }
 if(theme==='central-perk'){
  playFriendsSceneTransition(next);screen=next;window.scrollTo({top:0,behavior:'smooth'});
  const delay=window.matchMedia('(prefers-reduced-motion: reduce)').matches?0:520;
  friendsNavigationTimer=setTimeout(()=>{
   friendsNavigationTimer=null;app.classList.remove('friends-page-enter');render();app.dataset.friendsScene=next;
   if(document.body.dataset.theme==='central-perk'){void app.offsetWidth;app.classList.add('friends-page-enter');showFriendsEpisode(next)}
  },delay);
  return;
 }
 if(theme==='golden-snitch'){
  screen=next;render();app.dataset.friendsScene=next;
  app.classList.remove('hero-theme-page-enter','spider-page-enter');delete app.dataset.heroTheme;delete app.dataset.spiderRoute;
  window.scrollTo({top:0,behavior:'smooth'});
  return;
 }
 clearTimeout(pageTransitionTimer);
 document.querySelector('.borrowed-common-transition')?.remove();
 app.classList.remove('common-page-exit','common-page-enter','hero-theme-page-enter','spider-page-enter');
 delete app.dataset.heroTheme;delete app.dataset.spiderRoute;
 screen=next;
 const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 window.scrollTo({top:0,behavior:reduceMotion?'auto':'smooth'});
 if(reduceMotion){render();app.dataset.friendsScene=next;return}
 app.classList.add('common-page-exit');
 const scene=playCommonRouteTransition(next);
 pageTransitionTimer=setTimeout(()=>{
  app.classList.remove('common-page-exit');
  render();app.dataset.friendsScene=next;
  app.classList.remove('common-page-enter');void app.offsetWidth;app.classList.add('common-page-enter');
  pageTransitionTimer=setTimeout(()=>{
   app.classList.remove('common-page-enter');scene.remove();
  },780);
 },240);
}
function bindCards(){app.querySelectorAll('.item-card').forEach(c=>c.addEventListener('click',e=>{if(e.target.closest('[data-fav]')){e.stopPropagation();const id=c.dataset.id;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();e.target.textContent=state.favorites.includes(id)?'♥':'♡';e.target.style.color=state.favorites.includes(id)?'#da826e':'';return}openItem(c.dataset.id)}));}
