function attachReviewActions(){if(screen!=='activity')return;app.querySelectorAll('.activity-card').forEach(card=>{if(!card.querySelector('.status-pill.done')||card.querySelector('[data-review]'))return;const tx=state.transactions.find(t=>t.status==='Completed'&&t.name===card.querySelector('.activity-main b')?.textContent&&!t.reviewed);if(!tx)return;const button=document.createElement('button');button.className='review-action';button.dataset.review=tx.id;button.textContent='Leave a review';button.addEventListener('click',()=>{document.querySelector('#review-item-name').textContent='Your experience with '+tx.name;document.querySelector('#submit-review').dataset.tx=tx.id;document.querySelector('#review-dialog').showModal()});(card.querySelector('.activity-actions')||card).append(button)});}
const reviewObserver=new MutationObserver(attachReviewActions);reviewObserver.observe(app,{childList:true,subtree:true});
const interfaceEnhancer=new MutationObserver(()=>{if(screen==='activity'){app.querySelectorAll('.activity-card').forEach(card=>{const direction=card.querySelector('.activity-main p')?.textContent||'';if(!/^(Borrowing from|Requested by)/.test(direction)||card.querySelector('.borrow-timeline'))return;const status=card.querySelector('.status-pill')?.textContent||'Pending',steps=['Requested','Approved','Returned'],active=status==='Completed'?3:status==='Approved'?2:1,bar=document.createElement('div');bar.className='borrow-timeline';bar.setAttribute('aria-label',`Borrowing progress: ${status}`);bar.innerHTML=steps.map((s,i)=>`<span class="${i<active?'reached':''}">${s}</span>`).join('');card.append(bar)})}if(screen==='profile'){const cols=app.querySelector('.profile-columns');if(cols&&!app.querySelector('#saved-items-shortcut')){const saved=document.createElement('button');saved.id='saved-items-shortcut';saved.className='outline-button record-lend';saved.textContent=`♡ View saved listings (${state.favorites.length})`;saved.addEventListener('click',()=>{showSavedOnly=true;category='All';go('explore')});cols.prepend(saved);const help=document.createElement('section');help.className='help-card';help.innerHTML='<span class="eyebrow">HELP & SAFETY</span><h3>Borrow responsibly</h3><p>Meet at public campus pickup points, agree on the item condition and return time in chat, and report any issue through campus support. Don’t share room numbers or passwords.</p>';cols.append(help)}}});interfaceEnhancer.observe(app,{childList:true,subtree:true});
