// Supabase-backed mode. The project URL and publishable key are public browser
// values; authorization is enforced by Supabase Auth, RLS, and database RPCs.
const cloud=window.BorrowedBackend;
let cloudMode=false,cloudUser=null,authMode='signin',knownPendingRequestIds=null,autoRefreshBusy=false;
const authDialog=document.querySelector('#auth-dialog');
const authMessage=document.querySelector('#auth-message');
const authTitle=document.querySelector('#auth-title');
const authSubmit=document.querySelector('#auth-submit');
function setAuthMode(mode){authMode=mode;authTitle.textContent=mode==='signup'?'Create your campus account':'Sign in to your campus';authSubmit.innerHTML=mode==='signup'?'Create account <span>↗</span>':'Sign in <span>↗</span>';document.querySelector('#auth-name').hidden=mode!=='signup';document.querySelector('#auth-name').previousElementSibling.hidden=mode!=='signup';document.querySelector('#auth-password').autocomplete=mode==='signup'?'new-password':'current-password';document.querySelector('#auth-switch').textContent=mode==='signup'?'Already have an account? Sign in':'New here? Create an account';}
function statusText(value){return ({pending:'Pending',approved:'Approved',declined:'Declined',completed:'Completed',disputed:'Disputed'})[value]||value}
function isSrmEmail(email){return /^[^\s@]+@srmist\.edu\.in$/i.test(email.trim())}
function emojiFor(category,name=''){const n=name.toLowerCase();if(/dictionary|book|notebook|textbook/.test(n))return '📖';if(/calculator|calc/.test(n))return '🧮';if(/racket|racquet|badminton/.test(n))return '🏸';if(/suitcase|luggage|trolley/.test(n))return '🧳';if(/drill/.test(n))return '🪛';if(/umbrella/.test(n))return '☂️';if(/charger|cable|usb|adapter|hub/.test(n))return '🔌';if(/laptop|computer/.test(n))return '💻';if(/headphone|earphone/.test(n))return '🎧';if(/lamp|light/.test(n))return '💡';if(/tripod|camera/.test(n))return '📷';if(/first aid|medical/.test(n))return '🩹';if(/tool|screwdriver/.test(n))return '🧰';return ({Electronics:'🔌',Sports:'🏸',Study:'📚',Everyday:'🧰'})[category]||'📦'}
function itemPhotoMarkup(item,detail=false){return item.imagePath&&/^data:image\/(jpeg|png|webp);base64,/i.test(item.imagePath)?`<img class="item-photo${detail?' detail-photo':''}" src="${esc(item.imagePath)}" alt="${esc(item.name)}">`:''}
function itemVisualMarkup(item,detail=false){return itemPhotoMarkup(item,detail)||`<span class="item-emoji">${item.emoji||emojiFor(item.category,item.name)}</span>`}
function readItemPhoto(file){return new Promise((resolve,reject)=>{if(!file){resolve('');return}if(file.size>12000000){reject(new Error('Choose a photo smaller than 12 MB.'));return}if(!file.type.startsWith('image/')){reject(new Error('Choose an image file.'));return}const reader=new FileReader();reader.onerror=()=>reject(new Error('Could not read that photo.'));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error('Could not open that photo.'));image.onload=()=>{const scale=Math.min(1,520/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);let quality=.58,compressed=canvas.toDataURL('image/jpeg',quality);while(compressed.length>150000&&quality>.32){quality-=.06;compressed=canvas.toDataURL('image/jpeg',quality)}resolve(compressed)};image.src=reader.result};reader.readAsDataURL(file)})}
async function cloudLoad(){
 const uid=cloud.uid;
 const [profileRows,availableRows,ownRows,profiles,wishes,ledger]=await Promise.all([
  cloud.select('profiles',`select=*&id=eq.${uid}`),
  cloud.select('items','select=*&is_available=eq.true&order=created_at.desc'),
  cloud.select('items',`select=*&owner_id=eq.${uid}&order=created_at.desc`),
  cloud.select('profiles','select=id,display_name,reliability_score,avatar_path'),
  cloud.select('wishlist_requests',`select=*&user_id=eq.${uid}&order=created_at.desc`),
  cloud.select('credit_ledger',`select=*&user_id=eq.${uid}&order=created_at.desc&limit=50`)
 ]);
 const byProfile=new Map(profiles.map(p=>[p.id,p]));
 let itemRows=[...new Map([...availableRows,...ownRows].map(i=>[i.id,i])).values()];
 const ownIds=ownRows.map(i=>i.id);
 const filter=ownIds.length?`select=*&or=(borrower_id.eq.${uid},item_id.in.(${ownIds.join(',')}))&order=created_at.desc`:`select=*&borrower_id=eq.${uid}&order=created_at.desc`;
 const requests=await cloud.select('borrow_requests',filter);
 const missingIds=requests.map(r=>r.item_id).filter(id=>!itemRows.some(i=>i.id===id));
 if(missingIds.length)itemRows=[...itemRows,...await cloud.select('items',`select=*&id=in.(${missingIds.join(',')})`)];
 const itemById=new Map(itemRows.map(i=>[i.id,i]));
 state.items=itemRows.map(i=>{const owner=byProfile.get(i.owner_id)||{};return {id:i.id,name:i.name,category:i.category,credits:i.credit_cost,unit:'day',distance:i.pickup_zone||'Campus',owner:owner.display_name||'Campus member',ownerId:i.owner_id,initial:(owner.display_name||'?').slice(0,1).toUpperCase(),rating:'New',ownerAvatarPath:owner.avatar_path,condition:i.condition,emoji:emojiFor(i.category,i.name),bg:'#e8efe6',description:i.description,mine:i.owner_id===uid,x:25+(parseInt(i.id.slice(0,2),16)%60),y:25+(parseInt(i.id.slice(2,4),16)%55),pickupLat:i.pickup_lat,pickupLng:i.pickup_lng,pickupZone:i.pickup_zone,imagePath:i.image_path,availableFrom:i.available_from,availableUntil:i.available_until,available:i.is_available}});
 const profile=profileRows[0];
 if(profile){state.credits=profile.credits;state.trust=profile.reliability_score;state.profileName=profile.display_name;state.profileCampus=profile.campus;state.avatarPath=profile.avatar_path||'';state.profileEmail=cloudUser?.email||''}
 state.requests=wishes.map(r=>({id:r.id,name:r.item_name,note:r.details,status:r.status,urgent:r.urgent,created:r.created_at}));
 state.ledger=ledger.map(l=>({delta:l.delta,label:l.reason,created:l.created_at}));
 const previousPending=knownPendingRequestIds;
 state.transactions=requests.map(r=>{const i=itemById.get(r.item_id)||{};const borrower=byProfile.get(r.borrower_id)||{};const owner=byProfile.get(i.owner_id)||{};const direction=r.borrower_id===uid?'borrowed':'lent';return {id:r.id,requestId:r.id,itemId:r.item_id,name:i.name||'Shared item',emoji:emojiFor(i.category,i.name),direction,person:direction==='borrowed'?(owner.display_name||'Item owner'):(borrower.display_name||'Borrower'),status:statusText(r.status),cost:(i.credit_cost||1)*r.days,created:r.created_at,ownerId:i.owner_id,borrowerId:r.borrower_id,reviewed:false,returned:r.borrower_returned&&r.owner_returned,dueAt:r.due_at,extensionPending:r.extension_status==='pending',extensionDays:r.extension_days||0,hiddenForMe:direction==='borrowed'?r.hidden_by_borrower===true:r.hidden_by_owner===true}});
 const nextPending=new Set(state.transactions.filter(t=>t.direction==='lent'&&t.status==='Pending').map(t=>t.id));
 if(previousPending){const incoming=state.transactions.find(t=>nextPending.has(t.id)&&!previousPending.has(t.id));if(incoming)showToast(`New request for ${incoming.name} from ${incoming.person}.`)}
 knownPendingRequestIds=nextPending;
 persist();render();
 const lend=document.querySelector('#record-lend');if(lend)lend.hidden=true;
}
// Keep the signed-in activity screen current while it is open; owners see new
// requests without needing to reload. Refresh again when the tab becomes visible.
setInterval(async()=>{if(!cloudMode||!cloudUser||document.visibilityState!=='visible'||autoRefreshBusy)return;autoRefreshBusy=true;try{await cloudLoad()}catch(err){console.warn('Background refresh failed:',err)}finally{autoRefreshBusy=false}},15000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&cloudMode&&cloudUser&&!autoRefreshBusy){autoRefreshBusy=true;cloudLoad().catch(err=>console.warn('Background refresh failed:',err)).finally(()=>{autoRefreshBusy=false})}});
 async function initCloud(){
 if(!cloud?.configured)return;
 cloudMode=true;setAuthMode('signin');
 try{cloudUser=await cloud.currentUser();if(cloudUser&&!isSrmEmail(cloudUser.email)){await cloud.signOut();cloudUser=null}if(cloudUser){await cloudLoad();authDialog.close();return}}catch{}
 authMessage.textContent='SRM students: sign in with your @srmist.edu.in email. Listings are visible to SRM email accounts only.';
 authDialog.showModal();
}
function cloudError(error){console.error('Borrowed backend:',error);showToast(error?.message||'Could not reach the backend. Check your connection and try again.')}
let activeChatTransaction=null,chatRefreshTimer=null;
const contactDialog=document.querySelector('#contact-dialog');
function safePhoneHref(phone){const clean=String(phone||'').replace(/[^0-9+]/g,'');return /^([+]91)?[6-9][0-9]{9}$/.test(clean)?clean:''}
async function refreshBorrowChat(){let tx=activeChatTransaction;if(!tx||!cloudUser)return;const latest=state.transactions.find(t=>t.id===tx.id);if(latest){tx=latest;activeChatTransaction=latest}if(!['Pending','Approved'].includes(tx.status)){contactDialog.close();showToast('This request chat is closed.');return}const [messages,contacts]=await Promise.all([cloud.select('borrow_messages',`select=id,sender_id,body,created_at&request_id=eq.${tx.id}&order=created_at.asc`),tx.status==='Approved'?cloud.select('borrow_contacts',`select=user_id,phone,shared_at&request_id=eq.${tx.id}`):Promise.resolve([])]);const thread=document.querySelector('#contact-messages');thread.innerHTML=messages.map(m=>`<div class="chat-message ${m.sender_id===cloud.uid?'mine':''}"><p>${esc(m.body)}</p><small>${new Date(m.created_at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')||'<div class="chat-empty">Say hello to coordinate the campus handover.</div>';thread.scrollTop=thread.scrollHeight;const own=contacts.find(c=>c.user_id===cloud.uid),other=contacts.find(c=>c.user_id!==cloud.uid),peerName=tx.person||'the other student',otherPhone=other&&safePhoneHref(other.phone);document.querySelector('#contact-tools').innerHTML=`${otherPhone?`<div class="shared-contact"><div><b>${esc(peerName)}</b><small>${esc(other.phone)} · shared for this request</small></div><div class="contact-links"><a href="tel:${encodeURIComponent(otherPhone)}">Call</a><a href="sms:${encodeURIComponent(otherPhone)}">SMS</a></div></div>`:'<p class="contact-private">Phone numbers stay private unless a student chooses to share one.</p>'}${tx.status==='Approved'?(own?`<div class="own-contact"><span>Your number is shared: ${esc(own.phone)}</span><button type="button" class="outline-button" data-action="revoke-contact" data-tx="${tx.id}">Stop sharing</button></div>`:`<div class="share-contact"><label class="field-label" for="contact-phone">Share your number for this request</label><input class="field" id="contact-phone" type="tel" inputmode="tel" placeholder="+91 98765 43210" autocomplete="tel"><button type="button" class="outline-button" data-action="share-contact" data-tx="${tx.id}">Share number</button></div>`):'<p class="contact-private">Call and SMS options unlock after the owner approves. You can message here now.</p>'}`}
async function openBorrowChat(tx){if(!tx||!['Pending','Approved'].includes(tx.status))return;activeChatTransaction=tx;document.querySelector('#contact-title').textContent=tx.name;document.querySelector('#contact-subtitle').textContent=`Chat with ${tx.person} · request ${tx.status.toLowerCase()}`;contactDialog.showModal();try{await refreshBorrowChat()}catch(err){cloudError(err)}clearInterval(chatRefreshTimer);chatRefreshTimer=setInterval(()=>{if(contactDialog.open)refreshBorrowChat().catch(err=>console.warn('Message refresh failed:',err))},4000)}
contactDialog.addEventListener('close',()=>{activeChatTransaction=null;clearInterval(chatRefreshTimer)});
document.querySelector('#message-form').addEventListener('submit',async e=>{e.preventDefault();const tx=activeChatTransaction,input=document.querySelector('#message-input'),body=input.value.trim();if(!tx||!body)return;const button=e.currentTarget.querySelector('button');button.disabled=true;try{await cloud.rpc('send_borrow_message',{p_request_id:tx.id,p_body:body});input.value='';await refreshBorrowChat()}catch(err){cloudError(err)}finally{button.disabled=false;input.focus()}});
document.querySelector('#cancel-delete-activity').addEventListener('click',()=>document.querySelector('#delete-activity-dialog').close());
document.querySelector('#confirm-delete-activity').addEventListener('click',async e=>{const button=e.currentTarget,ids=[...selectedActivityIds];if(!ids.length)return;button.disabled=true;button.textContent='Deleting…';try{if(cloudMode&&cloudUser){const deleted=await cloud.rpc('delete_borrow_requests',{p_request_ids:ids});if(Number(deleted)!==ids.length)throw new Error('Some records could not be deleted. Refresh Activity and try again.');selectedActivityIds.clear();activitySelectionMode=false;await cloudLoad()}else{state.transactions=state.transactions.filter(t=>!selectedActivityIds.has(t.id));persist();selectedActivityIds.clear();activitySelectionMode=false;render()}document.querySelector('#delete-activity-dialog').close();showToast(`Deleted ${ids.length} activity record${ids.length===1?'':'s'}.`)}catch(err){cloudError(err)}finally{button.disabled=false;button.textContent='Delete permanently'}});
document.querySelector('#cancel-delete-wishlist').addEventListener('click',()=>document.querySelector('#delete-wishlist-dialog').close());
document.querySelector('#confirm-delete-wishlist').addEventListener('click',async e=>{const button=e.currentTarget,ids=[...selectedWishlistIds];if(!ids.length)return;button.disabled=true;button.textContent='Deleting…';try{if(cloudMode&&cloudUser){const deleted=await cloud.rpc('delete_wishlist_requests',{p_request_ids:ids});if(Number(deleted)!==ids.length)throw new Error('Some requests could not be deleted. Refresh and try again.');selectedWishlistIds.clear();wishlistSelectionMode=false;await cloudLoad()}else{state.requests=state.requests.filter(r=>!selectedWishlistIds.has(r.id));persist();selectedWishlistIds.clear();wishlistSelectionMode=false;renderActivity()}document.querySelector('#delete-wishlist-dialog').close();showToast(`Deleted ${ids.length} wishlist request${ids.length===1?'':'s'}.`)}catch(err){cloudError(err)}finally{button.disabled=false;button.textContent='Delete permanently'}});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action="message"],[data-action="share-contact"],[data-action="revoke-contact"]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();const tx=state.transactions.find(t=>t.id===button.dataset.tx);try{if(button.dataset.action==='message'){await openBorrowChat(tx);return}if(button.dataset.action==='share-contact'){const phone=safePhoneHref(document.querySelector('#contact-phone')?.value);if(!phone)throw new Error('Enter a valid 10-digit Indian mobile number.');await cloud.rpc('share_borrow_contact',{p_request_id:button.dataset.tx,p_phone:phone});await refreshBorrowChat();showToast('Your number is shared for this request.');return}await cloud.rpc('revoke_borrow_contact',{p_request_id:button.dataset.tx});await refreshBorrowChat();showToast('Your number is no longer shared.')}catch(err){cloudError(err)}},true);
authSubmit.addEventListener('click',async e=>{e.preventDefault();authSubmit.disabled=true;authMessage.textContent='Connecting securely…';try{const email=document.querySelector('#auth-email').value.trim(),pw=document.querySelector('#auth-' + 'pass' + 'word').value,name=document.querySelector('#auth-name').value.trim();if(!email||!pw)throw new Error('Enter your email and password.');if(!isSrmEmail(email))throw new Error('Use your SRM email ending in @srmist.edu.in.');let result;if(authMode==='signup'){if(pw.length<8)throw new Error('Use a password with at least 8 characters.');result=await cloud.signUp(email,pw,name||'Campus member');if(!result.access_token){authMessage.textContent='Check your SRM inbox to confirm your account, then sign in here.';setAuthMode('signin');return}}else result=await cloud.signIn(email,pw);cloudUser=result.user||await cloud.currentUser();if(!isSrmEmail(cloudUser?.email))throw new Error('Use an SRM email ending in @srmist.edu.in.');await cloudLoad();authDialog.close();showToast('You’re signed in. SRM campus listings are ready.')}catch(err){if(authMode==='signin'&&/invalid login credentials|invalid credentials/i.test(err.message)){setAuthMode('signup');authMessage.textContent='We could not sign in with those details. Create an account below if you are new, or switch back and check your password.';return}authMessage.textContent=err.message;cloudError(err)}finally{authSubmit.disabled=false}});
document.querySelector('#auth-switch').addEventListener('click',()=>{setAuthMode(authMode==='signin'?'signup':'signin');authMessage.textContent=authMode==='signup'?'Create an account with an email ending in @srmist.edu.in. Confirm it from your inbox to finish.':'Sign in with your @srmist.edu.in email.'});
document.addEventListener('click',async e=>{if(!e.target.closest('#sign-out'))return;try{await cloud.signOut();cloudUser=null;authDialog.showModal();setAuthMode('signin');authMessage.textContent='You have signed out.'}catch(err){cloudError(err)}});
authDialog.addEventListener('cancel',e=>{if(cloudMode&&!cloudUser)e.preventDefault()});

// Intercept demo-only local mutations and write them through authenticated RLS/RPC APIs.
document.addEventListener('click',async e=>{
 if(!cloudMode||!cloudUser)return;
 const borrow=e.target.closest('#borrow-button');
 if(borrow){e.preventDefault();e.stopImmediatePropagation();if(borrow.disabled)return;borrow.disabled=true;borrow.textContent='Sending request…';try{const name=document.querySelector('#item-content .detail-title')?.textContent;const item=state.items.find(i=>i.name===name);if(!item)throw new Error('Could not find this listing. Refresh and try again.');if(state.transactions.some(t=>t.itemId===item.id&&t.direction==='borrowed'&&['Pending','Approved'].includes(t.status)))throw new Error('You already have a pending or active request for this item.');const days=Math.max(1,Math.min(14,+document.querySelector('#borrow-days').value||1));await cloud.rpc('create_borrow_request',{p_item_id:item.id,p_days:days});await cloudLoad();itemDialog.close();showToast('Request pending. The owner can approve or decline it.');if(document.body.dataset.theme==='central-perk')friendsMessage('The One Where You Wait for the Green Light. Your request is pending with the owner.')}catch(err){cloudError(err);borrow.disabled=false;borrow.innerHTML='Request to borrow <span>↗</span>'}return}
 const action=e.target.closest('[data-action]');
 if(action){e.preventDefault();e.stopImmediatePropagation();try{const tx=state.transactions.find(t=>t.id===action.dataset.tx);if(action.dataset.action==='hide'){if(!tx||!['Completed','Declined'].includes(tx.status))throw new Error('Only completed or declined activity can be removed.');await cloud.rpc('hide_borrow_request',{p_request_id:action.dataset.tx});await cloudLoad();showToast('Removed from your Activity.');return}if(tx?.direction==='borrowed'&&(action.dataset.action==='approve'||action.dataset.action==='decline'))throw new Error('Only the item owner can approve or decline this request.');const args={p_request_id:action.dataset.tx};if(action.dataset.action==='approve')await cloud.rpc('approve_borrow_request',args);if(action.dataset.action==='decline')await cloud.rpc('decline_borrow_request',args);if(action.dataset.action==='extend')await cloud.rpc('request_borrow_extension',{p_request_id:action.dataset.tx,p_extra_days:1});if(action.dataset.action==='extension-approve')await cloud.rpc('respond_borrow_extension',{p_request_id:action.dataset.tx,p_approve:true});if(action.dataset.action==='extension-decline')await cloud.rpc('respond_borrow_extension',{p_request_id:action.dataset.tx,p_approve:false});if(action.dataset.action==='return'){const result=await cloud.rpc('confirm_borrow_return',args);if(result==='waiting_for_other_confirmation'){await cloudLoad();showToast('Waiting for the other person to confirm the handover.');return}}await cloudLoad();if(action.dataset.action==='return'&&document.body.dataset.theme==='central-perk'){friendsMessage('The One Where Everything Gets Returned. Nice work closing the loop.');unlockFriendsAchievement('workflow')};showToast(action.dataset.action==='extend'?'Extension request sent to the lender.':action.dataset.action.startsWith('extension-')?'Extension decision saved.':'Transaction updated.')}catch(err){cloudError(err)}return}
 const review=e.target.closest('[data-review]');
 if(review){e.preventDefault();e.stopImmediatePropagation();const tx=state.transactions.find(t=>t.id===review.dataset.review);if(tx){document.querySelector('#review-item-name').textContent='Your experience with '+tx.name;document.querySelector('#submit-review').dataset.tx=tx.id;document.querySelector('#review-dialog').showModal()}return}
 if(e.target.closest('#submit-request')){e.preventDefault();e.stopImmediatePropagation();try{const name=document.querySelector('#request-name').value.trim();if(!name)throw new Error('Enter the item you need.');await cloud.insert('wishlist_requests',{user_id:cloud.uid,item_name:name,details:document.querySelector('#request-note').value.trim(),urgent:document.querySelector('#request-urgent').checked});await cloudLoad();document.querySelector('#request-dialog').close();document.querySelector('#request-name').value='';document.querySelector('#request-note').value='';document.querySelector('#request-urgent').checked=false;showToast('Your request is posted to the campus wishlist.')}catch(err){cloudError(err)}return}
 
 if(e.target.closest('#save-profile')){e.preventDefault();e.stopImmediatePropagation();let uploadedPath='',profileSaved=false;try{const display_name=document.querySelector('#profile-name').value.trim()||'Campus member',campus=document.querySelector('#profile-campus').value.trim(),previousPath=state.avatarPath||'';let avatar_path=previousPath;if(window.pendingProfilePhoto==='remove')avatar_path=null;else if(window.pendingProfilePhoto){const blob=await (await fetch(window.pendingProfilePhoto)).blob();uploadedPath=cloud.uid+'/'+Date.now()+'-'+crypto.randomUUID()+'.jpg';await cloud.uploadStorage('borrowed-avatars',uploadedPath,blob,'image/jpeg');avatar_path=uploadedPath}await cloud.update('profiles','id=eq.'+cloud.uid,{display_name,campus,avatar_path});profileSaved=true;if(previousPath&&previousPath!==avatar_path)await cloud.removeStorage('borrowed-avatars',[previousPath]).catch(err=>console.warn('Old profile photo cleanup failed:',err));window.pendingProfilePhoto=null;document.querySelector('#profile-photo').value='';await cloudLoad();document.querySelector('#profile-dialog').close();showToast('Profile updated.')}catch(err){if(uploadedPath&&!profileSaved)await cloud.removeStorage('borrowed-avatars',[uploadedPath]).catch(()=>{});cloudError(err)}return}
 if(e.target.closest('#submit-review')){e.preventDefault();e.stopImmediatePropagation();try{const tx=state.transactions.find(t=>t.id===document.querySelector('#submit-review').dataset.tx);if(!tx)throw new Error('Transaction not found.');const reviewee_id=tx.direction==='borrowed'?tx.ownerId:tx.borrowerId;await cloud.insert('reviews',{request_id:tx.id,reviewer_id:cloud.uid,reviewee_id,rating:+document.querySelector('#review-rating').value,comment:document.querySelector('#review-note').value.trim()});document.querySelector('#review-dialog').close();await cloudLoad();showToast('Review saved.')}catch(err){cloudError(err)}return}
 if(e.target.closest('#record-lend')){e.preventDefault();e.stopImmediatePropagation();showToast('Credits are awarded after the owner approves a real borrow request.');}
},true);
document.querySelector('#submit-listing').addEventListener('click',async e=>{if(!cloudMode)return;e.preventDefault();const button=e.currentTarget;let status=document.querySelector('#listing-feedback');if(!status){status=document.createElement('small');status.id='listing-feedback';status.className='pickup-help';status.setAttribute('role','status');button.insertAdjacentElement('afterend',status)}if(!cloudUser){status.textContent='Sign in with your SRM email before publishing.';return}button.disabled=true;button.textContent='Publishing…';status.textContent='Saving your listing…';try{const name=document.querySelector('#list-name').value.trim();if(name.length<2)throw new Error('Enter an item name with at least 2 characters.');const image_path=await readItemPhoto(document.querySelector('#list-photo').files[0]);const pickup=window.selectedPickup||{lat:12.8248,lng:0.0494};await cloud.insert('items',{owner_id:cloud.uid,name,image_path,category:document.querySelector('#list-category').value,credit_cost:Math.max(1,Math.min(10,+document.querySelector('#list-cost').value||1)),description:document.querySelector('#list-description').value.trim(),condition:'Available',available_from:document.querySelector('#list-available-from').value||null,available_until:document.querySelector('#list-available-until').value||null,pickup_zone:'Campus pickup point (approximate)',pickup_lat:pickup.lat,pickup_lng:pickup.lng});await cloudLoad();window.pendingListingPhoto='';document.querySelector('#list-photo').value='';document.querySelector('#list-photo-preview').hidden=true;document.querySelector('#list-dialog').close();showToast('Your listing is live for signed-in campus members.');if(document.body.dataset.theme==='central-perk')friendsMessage('The One Where You Share Something. Your listing is live.');go('profile');friendsCelebrateListing()}catch(err){status.textContent='Could not publish: '+(err?.message||'Please check your connection and try again.');cloudError(err)}finally{button.disabled=false;button.innerHTML='Publish listing <span>↗</span>'}});
initCloud();
